// CrowdStrike CQL for Ghost Patient Claims Detection
// Identifies claims submitted for deceased or incarcerated beneficiaries
| match(file="beneficiary_eligibility.csv", field=beneficiary_id, include=[beneficiary_status, status_effective_date])
| beneficiary_status="deceased" OR beneficiary_status="incarcerated"
| filter(service_date > status_effective_date)
| groupBy(provider_npi, function=[
    count(as=ghost_claims),
    sum(billed_amount, as=ghost_billed),
    count(field=beneficiary_id, distinct=true, as=ghost_beneficiaries),
    collect([beneficiary_status])
  ])
| ghost_claims > 5
| sort(ghost_billed, order=desc)

