| claim_date > now() - 365d
// Medical provider clustering
| groupBy(medical_provider, function=[
    count(field=accident_id, distinct=true, as=accident_count),
    count(field=claim_id, distinct=true, as=claim_count),
    collect([accident_id]),
    sum(claim_amount, as=total_claimed)
