// CrowdStrike CQL for Post-Compromise Inbox Rule Manipulation
// Correlates inbox rule creation with sign-in from new IP within 24h
Operation="New-InboxRule" OR Operation="Set-InboxRule" OR Operation="Enable-InboxRule"
| rename(field=@timestamp, as=RuleTime)
| selfJoinFilter(UserId, where=[
    {Operation="New-InboxRule" OR Operation="Set-InboxRule" OR Operation="Enable-InboxRule"},
    {ResultType="0"}
  ])
| rename(field=@timestamp[1], as=SigninTime)
| rename(field=IPAddress[1], as=SigninIP)
// Signin must be from a new IP seen for the first time within 24h
// and rule creation must follow the signin
| RuleTime > SigninTime
| time_diff_ms := RuleTime - SigninTime
| time_diff_ms < 86400000
| hours_after_new_ip := round(time_diff_ms / 3600000 * 10) / 10
| select([RuleTime, UserId, Operation, Parameters, ClientIP, SigninIP, hours_after_new_ip])

// CrowdStrike CQL for SIM Swap Network-Level API Detection
// Correlates SIM change signals with MFA authentication attempts
#repo="flame_telecom" #event_type="number_intelligence"
| case {
    sim_swap_recently="true" | sim_risk := "HIGH";
    device_mismatch="true" | sim_risk := "HIGH";
    call_forwarding_active="true" | sim_risk := "MEDIUM";
    * | sim_risk := "LOW";
  }
| sim_risk="HIGH" OR sim_risk="MEDIUM"
| selfJoinFilter(phone_number, where=[
    {#repo="flame_telecom" sim_risk="HIGH" OR sim_risk="MEDIUM"},
    {#repo="flame_banking" #event_type="mfa_events" mfa_channel="SMS"}
  ])
| select([@timestamp, phone_number, customer_id, sim_risk,
          sim_swap_recently, sim_swap_timestamp,
          device_mismatch, call_forwarding_active, mfa_result])
| sort(@timestamp, order=desc)

// CrowdStrike CQL for Crypto Token Rug Pull Early Warning
// On-chain and OSINT signals are ingested from blockchain monitoring pipeline
#repo="blockchain" #event_type="defi_events"
| case {
    liquidity_removal_pct > 80 | risk_score := 10;
    top5_holder_pct > 0.60 | risk_score := 7;
    has_hidden_mint="true" | risk_score := 8;
    has_hidden_pause="true" | risk_score := 6;
    liquidity_unlocked="true" | risk_score := 5;
    * | risk_score := 0;
