| select([@timestamp, token_address, token_name, risk_score,
          liquidity_removal_pct, top5_holder_pct,
          has_hidden_mint, has_hidden_pause, liquidity_unlocked])
| sort(risk_score, order=desc)

// CrowdStrike CQL for Employment Fraud Metadata Feature Detection
// Primary signal: telecommuting=0 AND company_logo=0 -> 92% fraud probability
#repo="job_platforms" #event_type="job_postings"
| case {
    telecommuting_flag=0 AND has_company_logo=0
      | fraud_risk_level := "HIGH" | fraud_probability := 0.92;
    has_company_logo=0 AND has_company_profile=0
      | fraud_risk_level := "HIGH" | fraud_probability := 0.85;
    * | fraud_risk_level := "REVIEW" | fraud_probability := 0.50;
  }
| fraud_risk_level="HIGH"
| select([@timestamp, posting_id, company_name, job_title, location,
          salary_range, fraud_risk_level, fraud_probability,
          telecommuting_flag, has_company_logo, has_company_profile])
| sort(fraud_probability, order=desc)

// CrowdStrike CQL for Gift Card Balance Probing Velocity Detection
// NRF FT1103: Monitor balance check endpoints for automated probing
#repo="retail" #event_type="giftcard_balance_check"
| groupBy(source_ip, function=[count(as=check_count), count(field=card_number, distinct=true, as=unique_cards), count(field=user_agent, distinct=true, as=unique_agents), collect([device_fingerprint])], span=1h)
| check_count > 50 OR unique_cards > 20
| case {
    check_count > 200 AND unique_cards > 100 | risk := "CRITICAL";
    check_count > 100 OR unique_cards > 50 | risk := "HIGH";
    check_count > 50 OR unique_cards > 20 | risk := "MEDIUM";
  }
| sort(check_count, order=desc)

// CrowdStrike CQL for Smishing Triad Domain Pattern Detection
// Matches Darcula com- prefix, Chenlun kit files, and toll-scam lures
#repo="web_proxy" #event_type="url_filtering"
| case {
    url=/^https?:\/\/com-[a-z0-9]+/ | smishing_indicator := "darcula_domain_pattern";
    url="*ResourceRedConfig.js*" | smishing_indicator := "chenlun_kit_fingerprint";
    url="*/ResourceConfig/urlConfig.json*" | smishing_indicator := "chenlun_kit_fingerprint";
    url=/(?i)(ezpass|sunpass|fastrak|ipass|toll-|parking-notice)/ | smishing_indicator := "toll_scam_lure";
  }
| smishing_indicator="*"
| domain_age_days < 30 OR NOT _exists_(domain_age_days)
| groupBy([smishing_indicator, domain, source_ip, url], function=[count(as=cnt)])
| sort(cnt, order=desc)

// CrowdStrike CQL for Thin-File Identity Clustering
// Detects 3+ thin-file applicants sharing address/phone/device within 180 days
credit_history_months<12 tradeline_count<3
| groupBy(address, function=[
    count(field=applicant_id, distinct=true, as=applicant_count),
    collect([applicant_id, phone, device_fingerprint, application_date, ssn_hash])
  ], span=180d)
| applicant_count >= 3
| shared_attribute_type := "address"
| sort(applicant_count, order=desc)

// CrowdStrike CQL for SSN Age and Issuance Mismatch
// Detects synthetic identity indicators via SSN-DOB-credit file inconsistencies
event_type="CREDIT_APPLICATION"
| ssn_dob_gap_years := ssn_issue_year_estimated - applicant_birth_year
| risk_indicator_type := case {
    applicant_stated_age > 25 AND credit_file_age_months < 18 | "late_credit_file";
    ssn_issue_year_estimated > applicant_birth_year | "ssn_postdates_birth";
    applicant_stated_age < 16 AND credit_inquiry_exists="true" | "minor_ssn_with_credit";
    * | "none";
  }
| risk_indicator_type != "none"
| select([applicant_id, application_date, applicant_stated_age,
          credit_file_age_months, ssn_issue_year_estimated,
          applicant_birth_year, ssn_dob_gap_years,
          risk_indicator_type, address, device_fingerprint])
| sort(application_date, order=desc)

// CrowdStrike CQL for Rapid Authorized User Addition
// Detects same individual added as authorized user on 3+ accounts in 30 days
event_type="authorized_user_added"
| groupBy(authorized_user_id, function=[
    count(account_id, distinct=true, as=distinct_account_count),
    collect([authorized_user_name, account_id, primary_account_holder_id, event_date])
  ])
| distinct_account_count >= 3
| addition_velocity_days := duration(min(event_date), max(event_date))
| sort(distinct_account_count, order=desc)

// CrowdStrike CQL for AI-Generated ID Document Detection
// Detects document submissions with metadata inconsistencies indicating AI generation
event_type="DOCUMENT_SUBMISSION"
| anomaly_type := case {
    document_ai_score > 0.7 | "high_ai_score";
    pdf_creator = /Photoshop|GIMP|Stable Diffusion|Midjourney|DALL-E|unknown_ai_generator/
      AND exif_data_present = "false" | "suspicious_creator_no_exif";
    pdf_creation_date > pdf_modification_date | "timestamp_manipulation";
    dpi_consistency_check = "false" | "dpi_inconsistency";
    font_embedding_anomaly = "true" | "font_anomaly";
    * | "none";
  }
| anomaly_type != "none"
| select([applicant_id, submission_timestamp, document_type,
          document_ai_score, pdf_creator, exif_data_present,
          dpi_consistency_check, font_embedding_anomaly,
          anomaly_type, device_fingerprint, ip_address])
| sort(submission_timestamp, order=desc)

// CrowdStrike CQL for Crypto-Terror/Narco Nexus Detection
// Detects sanctions-exposed wallet transactions and peel chain patterns through mixers
(transaction_type="crypto_transfer" OR transaction_type="crypto_deposit" OR transaction_type="crypto_withdrawal")
amount_usd>=1000
(sdn_hop_distance<=2 OR (mixing_service_interaction="true" AND peel_chain_detected="true"))
| chain_classification := case {
    sdn_hop_distance<=1 -> "direct_sdn_exposure";
    sdn_hop_distance==2 -> "indirect_sdn_exposure";
    mixing_service_interaction=="true" AND peel_chain_detected=="true" -> "peel_chain_mixing";
    * -> "unknown";
  }
| groupBy(wallet_address, function=[
    collect([counterparty_wallet, amount_usd, crypto_currency, transaction_date,
             sdn_hop_distance, sdn_entity_name, mixing_service_interaction,
             peel_chain_detected, consolidation_wallet_risk_score,
             chain_classification]),
    sum(amount_usd, as=total_volume)
  ])
| sort(total_volume, order=desc)

// CrowdStrike CQL for Organized Insurance Claims Fraud
// Detects shared professional enablers and inception-proximate claim patterns
(claim_type="motor" OR claim_type="medical" OR claim_type="personal_injury")
| days_from_inception := dateDiff(policy_inception_date, claim_date, unit="days")
| groupBy(provider_id, function=[
    count(claim_id, as=provider_claim_count),
    collect([claimant_id, claim_amount, claim_date])
  ])
| provider_claim_count >= 2
| join({
    (claim_type="motor" OR claim_type="medical" OR claim_type="personal_injury")
    | groupBy(claimant_id, function=[
        count(claim_id, as=claimant_claim_count),
        collect([provider_id, legal_representative_id, claim_amount])
      ])
    | claimant_claim_count >= 3
  }, field=claimant_id)
| sort(provider_claim_count, order=desc)
